  const destination = inventorySourceLabel(item.inventorySource)
  if (!item.lifecycleStatus) return `Получен → ${destination}; складской учёт не завершён`

replacements.beforeBlock:
      title={panel.help}
    >
      {panel.label}
    </button>
  ))}
</div>

