  font-weight: 900;
  cursor: pointer;
}

.return-quantity-stepper > button:disabled {
  opacity: .45;
  cursor: default;
}

.return-quantity-stepper input {
  width: 100%;
  min-width: 0;
  text-align: center;
}

.return-quantity-stepper .return-quantity-all {
  padding-inline: 10px;
  white-space: nowrap;
  font-weight: 750;
}

@media (max-width: 760px) {
  .intake-queue {
    margin-inline: 0;
    padding: 13px;
  }

  .intake-queue-head,
  .intake-queue-missing {
    align-items: stretch;
    flex-direction: column;
  }

  .intake-queue-count {
    align-self: flex-start;
  }

  .intake-queue-row {
    grid-template-columns: 1fr;
  }

  .intake-queue-context {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .intake-queue-context > div {
    min-width: 0;
  }

  .intake-queue-action {
    width: 100%;
  }

  .return-quantity-stepper {
    grid-template-columns: 40px minmax(62px, 1fr) 40px;
  }

  .return-quantity-stepper .return-quantity-all {
    grid-column: 1 / -1;
    width: 100%;
  }
}
